sys_ui_action.client_script_v2:
function onClick(g_form) {

    g_modal.confirm("Confirmação", "Deseja realizar o Distrato?", function(confirmed) {
        if (confirmed) {
            // Exibe a mensagem "Aguarde..." imediatamente
            g_form.clearMessages(); // Limpa mensagens anteriores, se houver.
            g_form.addInfoMessage('Aguarde...');

            // Executa o submit e aguarda a finalização para exibir a mensagem de sucesso.
            g_form.submit('intregaSapDistrato')
                .then(function() {
                    // Após o submit ser concluído com sucesso
                    g_form.clearMessages();
                    g_form.addInfoMessage('Processo concluído com sucesso!');
                })
                .catch(function(error) {
                    // Em caso de erro, exibe uma mensagem apropriada
                    g_form.clearMessages();
                    g_form.addErrorMessage('Ocorreu um erro durante o processo: ' + error.message);
                });
        }
    });
}

sys_ui_action.script:
function intregaSapDistrato() {
    gsftSubmit(null, g_form.getFormElement(), 'intregaSapDistrato');
}
if (typeof window == 'undefined') {
    integrateContract();
}

function integrateContract() {
    (function() {

        try {
            var rec_id = current.sys_id;
            var gr = new GlideRecord('x_asscs_allos_o2c_task');
            if (gr.get(rec_id)) {
                var inputs = {};
                inputs['current'] = current; // GlideRecord of table:  
                //inputs['changed_fields'] = ; // Array.Object 
                inputs['table_name'] = 'x_asscs_allos_o2c_task';
                sn_fd.FlowAPI.getRunner().flow('x_asscs_integra.integra_contrato__distrato').inForeground().withInputs(inputs).run();
            }
        } catch (ex) {
            var message = ex.getMessage();
            gs.error(message);
        }

    })();
}
